library(shiny)

ui <- fluidPage(

  tags$head(tags$style(HTML("
  body { background-color: #111; color: white; }

  .big-btn { 
    height: 110px; 
    font-size: 24px; 
    font-weight: bold;
    margin: 8px 0; 
    border-radius: 14px;
  }

  .big-btn:active {
    transform: scale(0.97);
    opacity: 0.85;
  }

  .section-title {
    font-size: 22px;
    margin-top: 12px;
    color: white;
  }

  .stat-box {
  padding: 10px;
  border-radius: 10px;
  margin-bottom: 8px;
  text-align: center;
  font-size: 18px;
  font-weight: bold;
  border: 2px solid white;
  }

  #mm { background-color: #E6ACA1; color: white; border: 3px solid white; }
  #mf { background-color: #F54927; color: white; border: 3px solid white; }
  #fm { background-color: #C82909; color: white; border: 3px solid white; }
  #ff { background-color: #701705; color: white; border: 3px solid white; }

  .stat-mm { background-color: rgba(230,172,161,0.5); }  /* MMP→MMP */
  .stat-mf { background-color: rgba(245,73,39,0.5); }    /* MMP→FMP */
  .stat-fm { background-color: rgba(200,41,9,0.5); }     /* FMP→MMP */
  .stat-ff { background-color: rgba(112,23,5,0.5); }     /* FMP→FMP */

  .stat-turnover { background-color: rgba(20,20,20,0.5); }
  .stat-assist   { background-color: rgba(14,204,14,0.5); }

  input[type='radio'] {
  transform: scale(1.8);
  margin-right: 10px;
  cursor: pointer;
  }

  .radio-inline, .radio label {
  font-size: 20px;
  margin-right: 18px;
  cursor: pointer;
  }

  .shiny-options-group {
  margin-top: 6px;
  }
  "))),

  titlePanel("Bristol Mixed Pass Tracker"),

  div(class = "section-title", "Live Stats"),

  fluidRow(
    column(6, div(class="stat-box stat-mm", textOutput("count_mm"))),
    column(6, div(class="stat-box stat-mf", textOutput("count_mf")))
  ),
  fluidRow(
    column(6, div(class="stat-box stat-fm", textOutput("count_fm"))),
    column(6, div(class="stat-box stat-ff", textOutput("count_ff")))
  ),
  fluidRow(
    column(6, div(class="stat-box stat-turnover", textOutput("count_turnovers"))),
    column(6, div(class="stat-box stat-assist", textOutput("count_assists")))
  ),

  div(class = "section-title", "Outcome"),
  radioButtons(
    "outcome", NULL,
    choices = c("Completed", "Turnover", "Assist"),
    selected = "Completed",
    inline = TRUE
  ),

  div(class = "section-title", "Record Pass"),

  actionButton("mm", "MMP → MMP", class = "btn-primary big-btn"),
  actionButton("mf", "MMP → FMP", class = "btn-info big-btn"),
  actionButton("fm", "FMP → MMP", class = "btn-warning big-btn"),
  actionButton("ff", "FMP → FMP", class = "btn-success big-btn"),

  br(),
  actionButton("undo", "Undo Last Entry", class = "btn-danger"),

  br(), br(),
  downloadButton("download", "Download Game Data")
)

server <- function(input, output, session) {

  rv <- reactiveValues(data = data.frame(
    Timestamp = character(),
    From = character(),
    To = character(),
    Outcome = character(),
    stringsAsFactors = FALSE
  ))

  add_pass <- function(from, to) {
    new_row <- data.frame(
      Timestamp = as.character(Sys.time()),
      From = from,
      To = to,
      Outcome = input$outcome,
      stringsAsFactors = FALSE
    )
    rv$data <- rbind(rv$data, new_row)

  }

  output$count_mm <- renderText({
    paste("MMP → MMP:",
          sum(rv$data$From == "MMP" & rv$data$To == "MMP"))
  })

  output$count_mf <- renderText({
    paste("MMP → FMP:",
          sum(rv$data$From == "MMP" & rv$data$To == "FMP"))
  })

  output$count_fm <- renderText({
    paste("FMP → MMP:",
          sum(rv$data$From == "FMP" & rv$data$To == "MMP"))
  })

  output$count_ff <- renderText({
    paste("FMP → FMP:",
          sum(rv$data$From == "FMP" & rv$data$To == "FMP"))
  })

  output$count_turnovers <- renderText({
    paste("Turnovers:",
          sum(rv$data$Outcome == "Turnover"))
  })

  output$count_assists <- renderText({
    paste("Assists:",
          sum(rv$data$Outcome == "Assist"))
  })

  observeEvent(input$mm, { add_pass("MMP", "MMP") })
  observeEvent(input$mf, { add_pass("MMP", "FMP") })
  observeEvent(input$fm, { add_pass("FMP", "MMP") })
  observeEvent(input$ff, { add_pass("FMP", "FMP") })
  observeEvent(input$undo, {
    if (nrow(rv$data) > 0) {
      rv$data <- rv$data[-nrow(rv$data), ]
    }
  })

  output$download <- downloadHandler(
    filename = function() {
      paste0("ultimate_pass_data_", Sys.Date(), ".csv")
    },
    content = function(file) {
      write.csv(rv$data, file, row.names = FALSE)
    }
  )
}

shinyApp(ui, server)
